package com.storemate.backend.web;
import com.storemate.backend.domain.*;import com.storemate.backend.repo.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.transaction.annotation.Transactional;
import javax.imageio.ImageIO;import java.awt.image.BufferedImage;import java.io.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest @Transactional class ProductPhotoIntegrationTest {
 @Autowired ProductPhotoController photo;@Autowired InventoryController inventory;@Autowired AccountRepository accounts;@Autowired StoreRepository stores;@Autowired StoreMemberRepository members;@Autowired ProductRepository products;@Autowired ProductPhotoRepository photos;
 Account owner,staff;Store store;
 @BeforeEach void setup(){String id=UUID.randomUUID().toString().substring(0,8);owner=accounts.save(new Account("photo-owner"+id,"unused",Role.OWNER,"사장","20000101"));staff=accounts.save(new Account("photo-staff"+id,"unused",Role.STAFF,"직원","20000101"));store=stores.save(new Store("사진 테스트","기타",null,null,null,"09:00","22:00",id,owner));members.save(new StoreMember(owner,store,Role.OWNER,MemberStatus.APPROVED));members.save(new StoreMember(staff,store,Role.STAFF,MemberStatus.APPROVED));products.saveAndFlush(new Product(store,"PHOTO-01","테스트 우유","냉장",2,0,null));}
 static String picture(int width,int height) throws IOException {var img=new BufferedImage(width,height,BufferedImage.TYPE_INT_RGB);var out=new ByteArrayOutputStream();ImageIO.write(img,"png",out);return Base64.getEncoder().encodeToString(out.toByteArray());}
 ProductPhotoController.Upload request(String version,String key) throws IOException{return new ProductPhotoController.Upload(picture(1200,600),version,key);}
 @Test void photoIsStoredAsBoundedJpegAndSharedAcrossApprovedMembers() throws Exception{var saved=photo.put(owner,store.getId(),"PHOTO-01",request(null,"photo-test-001"));photos.flush();var loaded=photo.get(staff,store.getId(),"PHOTO-01");assertEquals(saved,loaded);assertEquals("image/jpeg",loaded.contentType());var image=ImageIO.read(new ByteArrayInputStream(Base64.getDecoder().decode(loaded.imageBase64())));assertEquals(512,image.getWidth());assertEquals(256,image.getHeight());assertEquals(saved.version(),inventory.list(staff,store.getId()).getFirst().photoVersion());assertEquals(2,inventory.one(owner,store.getId(),"PHOTO-01").stock());}
 @Test void retryIsIdempotentAndStaleReplacementCannotOverwrite() throws Exception{var request=request(null,"photo-test-002");var first=photo.put(owner,store.getId(),"PHOTO-01",request);assertEquals(first,photo.put(owner,store.getId(),"PHOTO-01",request));assertThrows(ApiException.class,()->photo.put(staff,store.getId(),"PHOTO-01",request(null,"photo-test-003")));var replaced=photo.put(staff,store.getId(),"PHOTO-01",request(first.version(),"photo-test-004"));assertNotEquals(first.version(),replaced.version());assertEquals(1,photos.count());}
 @Test void malformedImagesAndOversizedRequestAreRejected(){assertThrows(ApiException.class,()->photo.put(owner,store.getId(),"PHOTO-01",new ProductPhotoController.Upload("invalid",null,"photo-test-005")));assertThrows(ApiException.class,()->photo.put(owner,store.getId(),"PHOTO-01",new ProductPhotoController.Upload("a".repeat(5600001),null,"photo-test-006")));assertThrows(ApiException.class,()->photo.get(owner,store.getId(),"PHOTO-01"));}
 @Test void outsiderCannotReadOrUploadPhoto() throws Exception{var stranger=accounts.save(new Account("photo-out"+UUID.randomUUID().toString().substring(0,8),"unused",Role.STAFF,"외부인","20000101"));photo.put(owner,store.getId(),"PHOTO-01",request(null,"photo-test-007"));assertThrows(ApiException.class,()->photo.get(stranger,store.getId(),"PHOTO-01"));assertThrows(ApiException.class,()->photo.put(stranger,store.getId(),"PHOTO-01",request(null,"photo-test-008")));}
 @Test void deleteAndRereceiveDoNotExposeOldPhoto() throws Exception{photo.put(owner,store.getId(),"PHOTO-01",request(null,"photo-test-009"));inventory.delete(owner,store.getId(),"PHOTO-01",2);assertThrows(ApiException.class,()->photo.get(owner,store.getId(),"PHOTO-01"));inventory.receive(owner,store.getId(),new Dto.ReceiptRequest(List.of(new Dto.ReceiptItem("PHOTO-01","새 우유","냉장",1,null)),"photo-receipt-001"));assertNull(inventory.one(owner,store.getId(),"PHOTO-01").photoVersion());assertThrows(ApiException.class,()->photo.get(owner,store.getId(),"PHOTO-01"));var saved=photo.put(owner,store.getId(),"PHOTO-01",request(null,"photo-test-010"));assertEquals(saved.version(),photo.get(owner,store.getId(),"PHOTO-01").version());}
}
